				deleteBody, _ = sjson.Set(deleteBody, "snmpEvent.attributes.owner", "DME_UNSET_PROPERTY_MARKER")
				deleteBody, _ = sjson.Set(deleteBody, "snmpEvent.attributes.trap", "DME_UNSET_PROPERTY_MARKER")
